:root{
  /* Kent Business College brand system */
  --kbc-navy:#061d28;
  --kbc-navy-secondary:#0d2d39;
  --kbc-navy-deep:#04141c;
  --kbc-teal:#0c7d78;
  --kbc-teal-light:#1aa79d;
  --kbc-gold:#d7b15a;
  --kbc-lime:#d9efaa;
  --kbc-text-primary:#12232c;
  --kbc-text-secondary:#60717a;
  --kbc-text-inverse:#ffffff;
  --kbc-text-on-gold:#172429;
  --kbc-surface-primary:#ffffff;
  --kbc-surface-warm:#f3f2ec;
  --kbc-surface-cool:#eef5f4;
  --kbc-surface-dark:#061d28;
  --kbc-border:rgba(18,35,44,.13);
  --kbc-border-dark:rgba(255,255,255,.16);
  --kbc-font-body:"DM Sans",Arial,Helvetica,sans-serif;
  --kbc-font-display:"Source Serif 4",Georgia,serif;
  --kbc-font-data:"Manrope",Arial,Helvetica,sans-serif;
  --kbc-container:min(1240px,calc(100% - 40px));
  --kbc-reading-width:720px;
  --kbc-space-1:4px;--kbc-space-2:8px;--kbc-space-3:12px;--kbc-space-4:16px;--kbc-space-5:20px;
  --kbc-space-6:24px;--kbc-space-7:28px;--kbc-space-8:32px;--kbc-space-10:40px;--kbc-space-12:48px;
  --kbc-space-14:56px;--kbc-space-16:64px;--kbc-space-18:72px;--kbc-space-20:80px;--kbc-space-24:96px;--kbc-space-28:112px;
  --kbc-radius-sm:10px;--kbc-radius-md:14px;--kbc-radius-lg:18px;--kbc-radius-xl:22px;
  --kbc-radius-2xl:26px;--kbc-radius-3xl:28px;--kbc-radius-pill:999px;--kbc-radius-circle:50%;
  --kbc-shadow-sm:0 10px 30px rgba(4,31,42,.08);
  --kbc-shadow-md:0 18px 50px rgba(4,31,42,.14);
  --kbc-shadow-lg:0 28px 90px rgba(4,31,42,.20);
  --kbc-shadow-feature:0 40px 100px rgba(0,0,0,.40);
  --kbc-transition-fast:.2s ease;--kbc-transition-default:.3s ease;--kbc-transition-reveal:.7s ease;

