  --ink:var(--kbc-text-primary);--ink-2:var(--kbc-navy-secondary);--muted:var(--kbc-text-secondary);--muted-2:#7f9098;
  --paper:var(--kbc-surface-primary);--paper-2:#f8faf9;--mist:var(--kbc-surface-cool);--cream:var(--kbc-surface-warm);
  --purple:var(--kbc-teal);--purple-2:var(--kbc-teal-light);--purple-3:var(--kbc-teal-light);
  --purple-deep:var(--kbc-navy);--purple-black:var(--kbc-navy-deep);
  --gold:var(--kbc-gold);--gold-2:var(--kbc-lime);--gold-soft:#f7edcf;
  --blue:var(--kbc-navy-secondary);--blue-soft:var(--kbc-surface-cool);--green:var(--kbc-teal);--green-soft:var(--kbc-surface-cool);
  --line:var(--kbc-border);--line-dark:var(--kbc-border-dark);
  --shadow-sm:var(--kbc-shadow-sm);--shadow-md:var(--kbc-shadow-md);--shadow-lg:var(--kbc-shadow-feature);
  --radius-sm:var(--kbc-radius-sm);--radius-md:var(--kbc-radius-md);--radius-lg:var(--kbc-radius-lg);
  --radius-xl:var(--kbc-radius-2xl);--round:var(--kbc-radius-pill);
  --container:1240px;--header-h:82px;
}
