.final-cta{background:radial-gradient(circle at 80% 20%,rgba(215,177,90,.17),transparent 25%),linear-gradient(135deg,var(--purple-deep),var(--purple));color:white;border-radius:34px;padding:52px;display:grid;grid-template-columns:1fr auto;gap:35px;align-items:center;box-shadow:var(--shadow-lg)}.final-cta small{color:var(--gold-2);text-transform:uppercase;letter-spacing:.15em;font-weight:800}.final-cta h2{font-family:"Source Serif 4",serif;font-size:clamp(40px,4.5vw,64px);line-height:.98;margin:10px 0}.final-cta p{color:#dce8e6;margin:0;max-width:720px}.final-actions{display:grid;gap:10px;min-width:225px}
.footer{margin-top:100px;background:var(--purple-black);color:#d7cadd;padding:58px 0 24px}.footer-grid{display:grid;grid-template-columns:1.2fr repeat(4,.8fr);gap:30px}.footer-logo img{width:190px;filter:none;background:#fff;padding:8px 10px;border-radius:14px;margin-bottom:14px}.footer p,.footer a{font-size:12px;line-height:1.8;color:#b9c9cb}.footer h4{font-size:12px;color:white;margin:0 0 13px}.footer ul{list-style:none;margin:0;padding:0;display:grid;gap:7px}.footer-note{margin-top:32px;padding-top:18px;border-top:1px solid rgba(255,255,255,.08);display:flex;justify-content:space-between;gap:20px;font-size:10px;color:#8da2a6}.legal-note{margin-top:12px;color:#9fb2b5;font-size:10px;line-height:1.65;max-width:760px}
.sticky-mobile-cta{display:none;position:fixed;left:12px;right:12px;bottom:12px;z-index:900;background:var(--gold);color:var(--purple-deep);padding:13px 16px;border-radius:14px;text-align:center;font-weight:800;box-shadow:0 18px 38px rgba(4,20,28,.28)}

/* =========================================================
   Kent Business College website-wide design-system refinements
   ========================================================= */
html{scroll-padding-top:110px}
body{font-family:var(--kbc-font-body);color:var(--kbc-text-primary);background:var(--kbc-surface-primary)}
button,input,select,textarea{font-family:var(--kbc-font-body)}
.container{width:var(--kbc-container)}
.section{padding:var(--kbc-space-28) 0}.section-compact{padding:78px 0}
.section-mist{background:var(--kbc-surface-cool)}.section-cream{background:var(--kbc-surface-warm)}.section-dark{background:var(--kbc-surface-dark)}
.announcement{background:var(--kbc-gold);color:var(--kbc-text-on-gold);letter-spacing:.06em}
.site-header{background:rgba(6,29,40,.96);backdrop-filter:blur(18px);box-shadow:0 10px 35px rgba(0,0,0,.18)}
.header-cta{min-height:44px;border-radius:var(--kbc-radius-sm);background:var(--kbc-gold);color:var(--kbc-text-on-gold)}
.btn{min-height:44px;padding:13px 18px;border-radius:var(--kbc-radius-sm);font-size:13px;transition:transform var(--kbc-transition-fast),box-shadow var(--kbc-transition-fast),background-color var(--kbc-transition-fast),border-color var(--kbc-transition-fast)}
.btn-primary{background:var(--kbc-gold);color:var(--kbc-text-on-gold)}
.btn-dark{background:var(--kbc-navy);color:#fff}.btn-outline{border-color:var(--kbc-border)}
.eyebrow,.route-label,.path-badge,.result-label,.control-head small,.strip-title small,.mega-label{font-family:var(--kbc-font-data)}
.section-heading h2,.hero-copy h1,.problem-copy h2,.panel-top h3,.builder-intro h2,.route-head h3,.ai-copy h2,.application-copy h3,.role-stage h3,.expert-body h3,.learning-copy h2,.eligibility-card h3,.eligibility-result h3,.faq-intro h2,.final-cta h2{font-family:var(--kbc-font-display);font-weight:600}
.section-heading h2{font-size:clamp(40px,5vw,62px);line-height:1.02;letter-spacing:-.035em}
.section-heading p,.problem-copy p,.ai-copy p,.learning-copy>p,.faq-intro p{max-width:var(--kbc-reading-width)}
.hero{background:radial-gradient(circle at 78% 23%,rgba(26,167,157,.23),transparent 27%),linear-gradient(110deg,#041923 0%,#082a36 58%,#071e28 100%);padding:94px 0;}
.hero:before{opacity:.72}.hero-copy h1{font-size:clamp(52px,6vw,84px);font-weight:600;line-height:.96;letter-spacing:-.048em}.hero-copy h1 span{color:var(--kbc-lime)}
.hero-copy>p{font-size:18px;line-height:1.6}.hero-photo{border-radius:var(--kbc-radius-3xl)}.control-tower{border-radius:var(--kbc-radius-xl)}
.hero-fact,.status,.credit-card .big,.credit-total strong,.credit-pill,.bursary-row strong,.route-highlight{font-family:var(--kbc-font-data)}
.status.green{color:var(--kbc-lime)}.live:before{background:var(--kbc-lime)}
.mega{border-radius:0 0 var(--kbc-radius-2xl) var(--kbc-radius-2xl)}
.mega-feature,.credit-card,.builder-summary,.eligibility-result{background:var(--kbc-navy)}
.control-map,.ai-stage{background:radial-gradient(circle at 78% 20%,rgba(26,167,157,.16),transparent 26%),linear-gradient(145deg,var(--kbc-navy),var(--kbc-navy-secondary));border-radius:var(--kbc-radius-3xl)}
.map-core,.ai-core{background:radial-gradient(circle at 35% 28%,#edf5ce,var(--kbc-lime) 48%,var(--kbc-gold));color:var(--kbc-text-primary)}
.path-panel,.builder-card,.route-card,.application-visual,.expert-card,.learning-photo,.eligibility-card{border-radius:var(--kbc-radius-2xl)}
.route-card,.path-panel,.builder-card,.expert-card{box-shadow:var(--kbc-shadow-sm)}
.route-card.bursary .route-head{background:linear-gradient(135deg,var(--kbc-navy),var(--kbc-navy-secondary))}
.application-visual{background:linear-gradient(145deg,var(--kbc-navy),var(--kbc-navy-secondary))}
.final-cta{border-radius:var(--kbc-radius-3xl);background:radial-gradient(circle at 80% 20%,rgba(26,167,157,.20),transparent 27%),linear-gradient(135deg,var(--kbc-navy),var(--kbc-navy-secondary));box-shadow:var(--kbc-shadow-lg)}
.footer{background:var(--kbc-navy-deep);color:rgba(255,255,255,.72)}
.footer h4{font-family:var(--kbc-font-data);text-transform:uppercase;letter-spacing:.14em;font-size:10px}
.footer p,.footer a{color:rgba(255,255,255,.72)}
.ai-ring,.ai-node,.map-node{animation:none}
.evidence-card:hover,.expert-card:hover,.route-card:hover{transform:translateY(-2px)}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--kbc-gold);outline-offset:3px}
@media(max-width:760px){:root{--kbc-container:min(100% - 28px,1240px)}.section{padding:72px 0}.hero{padding:64px 0 76px}.hero-copy h1{font-size:clamp(44px,13vw,48px)}.section-heading h2,.problem-copy h2,.builder-intro h2,.ai-copy h2,.learning-copy h2,.faq-intro h2{font-size:clamp(36px,10vw,40px)}}

@keyframes spin{from{transform:translate(-50%,-50%) rotate(0)}to{transform:translate(-50%,-50%) rotate(360deg)}}
@keyframes counterSpin{from{transform:rotate(0)}to{transform:rotate(-360deg)}}
@keyframes float{0%,100%{margin-top:0}50%{margin-top:-9px}}
@media(max-width:1180px){.main-nav{gap:15px}.main-nav>a:nth-of-type(4),.main-nav>a:nth-of-type(5){display:none}.hero-grid,.problem-grid,.ai-grid,.learning-grid{grid-template-columns:1fr}.hero-visual{min-height:620px}.pathway-shell,.builder-wrap,.faq-grid{grid-template-columns:1fr}.path-tabs,.builder-intro,.faq-intro,.eligibility-result{position:static}.path-tabs{grid-template-columns:repeat(4,1fr)}.path-tab:hover{transform:translateY(-2px)}.sector-strip-inner{grid-template-columns:repeat(3,1fr)}.strip-title{grid-column:1/-1;border-right:0;border-bottom:1px solid var(--line);padding-left:0}.roles-map,.maturity{grid-template-columns:repeat(2,1fr)}.footer-grid{grid-template-columns:1.3fr repeat(2,1fr)}}
@media(max-width:900px){.section{padding:86px 0}.section-compact{padding:64px 0}.main-nav,.audience-toggle,.header-cta{display:none}.menu-btn{display:block}.header-inner{height:72px}.brand img{width:172px}.section-heading{grid-template-columns:1fr;gap:20px}.hero{padding:52px 0 72px}.hero-grid{gap:36px}.hero-copy h1{max-width:none}.hero-visual{min-height:535px}.control-tower{width:300px}.sector-strip-inner{grid-template-columns:repeat(2,1fr)}.panel-top,.module-columns,.application-panel,.eligibility-grid{grid-template-columns:1fr}.routes-grid{grid-template-columns:1fr}.route-flow{grid-template-columns:1fr}.flow-arrow{transform:rotate(90deg)}.evidence-grid,.expert-grid{grid-template-columns:1fr 1fr}.footer-grid{grid-template-columns:1fr 1fr}.associate-banner,.final-cta{grid-template-columns:1fr}.final-actions{min-width:0}.panel-outcomes{grid-template-columns:1fr 1fr}.path-tabs{grid-template-columns:1fr 1fr}.maturity-cta{align-items:flex-start;flex-direction:column}}
@media(max-width:650px){body{padding-bottom:76px}.container{width:min(calc(100% - 28px),var(--container))}.announcement{font-size:10px}.hero-copy h1{font-size:48px}.hero-copy>p{font-size:16px}.hero-actions{display:grid}.hero-actions .btn{width:100%}.hero-visual{min-height:500px}.hero-photo{right:0}.control-tower{left:12px;right:12px;width:auto;bottom:18px}.crane-svg{display:none}.sector-strip-inner{grid-template-columns:1fr 1fr}.strip-item{min-height:80px}.path-tabs{grid-template-columns:1fr}.panel-top,.panel-body{padding:23px}.panel-top h3{font-size:35px}.module-columns,.panel-outcomes,.builder-modules,.application-points{grid-template-columns:1fr}.builder-card{padding:21px}.builder-head{display:block}.credit-total{text-align:left;margin-top:12px}.evidence-grid,.expert-grid,.roles-map,.maturity{grid-template-columns:1fr}.ai-stage{min-height:590px}.ai-ring.r1{width:340px;height:340px}.ai-ring.r2{width:270px;height:270px}.ai-core{width:170px;height:170px}.ai-node{min-width:108px;padding:10px 12px;font-size:11px}.ai-node.n1{top:92px}.ai-node.n2{right:7px;top:200px}.ai-node.n3{right:20px;bottom:98px}.ai-node.n4{left:20px;bottom:98px}.ai-node.n5{left:7px;top:220px}.ai-node.n6{bottom:54px}.learning-photo{min-height:430px}.faq-a p{padding-right:0}.footer-grid{grid-template-columns:1fr}.footer-note{display:block;padding-bottom:70px}.sticky-mobile-cta{display:block}.final-cta{padding:34px 24px}.associate-banner{padding:25px}.mega{display:none}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
@media print{.announcement,.site-header,.sticky-mobile-cta,.hero-actions,.btn,.footer{display:none!important}.hero{background:#fff;color:#000;padding:40px 0}.hero-copy>p,.hero-fact{color:#333}.section,.section-compact{padding:35px 0}.path-panel{display:block!important;break-inside:avoid}.path-tabs{display:none}.ai-stage,.control-map,.section-dark{background:#eee!important;color:#000!important}}

/* Energy sector visual refinements */
:root{--energy:var(--kbc-teal);--energy-2:var(--kbc-teal-light);--energy-soft:var(--kbc-surface-cool);--power:var(--kbc-gold)}
.application-visual.has-image{padding:0;background:var(--purple-deep)}
.application-visual.has-image:before{z-index:1;background:linear-gradient(180deg,rgba(4,20,28,.08),rgba(4,20,28,.78));background-size:auto}
.application-visual.has-image img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.application-image-copy{position:absolute;left:28px;right:28px;bottom:25px;z-index:2}
.application-image-copy small{color:var(--gold-2);font-weight:800;text-transform:uppercase;letter-spacing:.14em}
.application-image-copy h3{font-family:"Source Serif 4",serif;font-size:38px;line-height:1;margin:12px 0 0;max-width:10ch;color:white}
.hero-fact i{background:var(--kbc-teal-light)}
.sector-chip.active,.application-tab.active{border-color:var(--kbc-teal);box-shadow:inset 0 -2px 0 var(--kbc-teal)}
@media(max-width:720px){.application-image-copy h3{font-size:31px}.application-visual.has-image{min-height:330px}}

(() => {
  const audienceCopy = {
    employer:{title:'Build the capability to control <span>complex energy delivery.</span>',copy:'Develop project-controls capability across power generation, renewables, electricity networks, utilities, energy transition and major capital programmes. Choose the pathway that matches the responsibility your people carry today—and the level they are preparing to reach next.',secondary:'Check workforce eligibility'},
    professional:{title:'Move from reporting to <span>professional influence.</span>',copy:'Choose the pathway that reflects your energy-sector responsibility and the level you want to reach next—from operational project controls through strategic, PMO and chartered-readiness capability.',secondary:'Check my eligibility'}
  };
  const audienceButtons = [...document.querySelectorAll('[data-audience]')];
  function setAudience(mode){
    audienceButtons.forEach(b=>b.setAttribute('aria-pressed', String(b.dataset.audience===mode)));
    document.getElementById('heroTitle').innerHTML=audienceCopy[mode].title;
    document.getElementById('heroCopy').textContent=audienceCopy[mode].copy;
    document.getElementById('heroSecondary').textContent=audienceCopy[mode].secondary;
    try{localStorage.setItem('kbc-sector-audience',mode)}catch(e){}
  }
  audienceButtons.forEach(b=>b.addEventListener('click',()=>setAudience(b.dataset.audience)));
  try{setAudience(localStorage.getItem('kbc-sector-audience')||'employer')}catch(e){setAudience('employer')}

  const resourceWrap=document.getElementById('resourceWrap');
  const resourceTrigger=resourceWrap?.querySelector('.resource-trigger');
  resourceTrigger?.addEventListener('click',()=>{const open=resourceWrap.classList.toggle('open');resourceTrigger.setAttribute('aria-expanded',String(open))});
  document.addEventListener('click',e=>{if(resourceWrap && !resourceWrap.contains(e.target)){resourceWrap.classList.remove('open');resourceTrigger?.setAttribute('aria-expanded','false')}});

  const menuBtn=document.getElementById('menuBtn'),drawer=document.getElementById('mobileDrawer'),scrim=document.getElementById('scrim'),drawerClose=document.getElementById('drawerClose');
  function toggleDrawer(open){drawer.classList.toggle('open',open);scrim.classList.toggle('open',open);drawer.setAttribute('aria-hidden',String(!open));menuBtn.setAttribute('aria-expanded',String(open));document.body.style.overflow=open?'hidden':''}
  menuBtn.addEventListener('click',()=>toggleDrawer(true));drawerClose.addEventListener('click',()=>toggleDrawer(false));scrim.addEventListener('click',()=>toggleDrawer(false));drawer.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>toggleDrawer(false)));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleDrawer(false);resourceWrap?.classList.remove('open')}});

  const tabs=[...document.querySelectorAll('.path-tab')],panels=[...document.querySelectorAll('.path-panel')];
  function activatePath(index){tabs.forEach((t,i)=>{const active=i===index;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;panels[i].classList.toggle('active',active)});}
  tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activatePath(i));tab.addEventListener('keydown',e=>{let next=i;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(i+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==i){e.preventDefault();activatePath(next);tabs[next].focus()}})});

  const pathData={
    operational:{title:'Operational Pathway',target:6,hint:'Core credits are fixed. Choose three specialist options.',core:[['PMP preparation and professional development',2],['AI in Project Controls Certificate',1]],electives:[['PMI Scheduling Professional (PMI-SP)',1],['Earned Value Management (EVM)',1],['Risk Management',1],['Project Planning & Control (PPC)',1]],maxElectives:3},
    strategic:{title:'Strategic Pathway',target:6,hint:'Core credits are fixed. Choose three specialist options.',core:[['PMP preparation and professional development',2],['AI in Project Controls Certificate',1]],electives:[['Managing Successful Programmes (MSP)',1],['Managing Portfolios',1],['Risk Management',1],['Project Management Office (PMO)',1]],maxElectives:3},
    chartered:{title:'Chartered Pathway',target:6,hint:'Core credits are fixed. Choose one specialist option.',core:[['Certified PMO Professional Level 6',4],['AI in Project Controls Certificate',1]],electives:[['Portfolio Management',1],['Earned Value Management',1]],maxElectives:1},
    pmo:{title:'PMO Certified',target:4,hint:'A fixed four-credit route with no elective selection.',core:[['Certified PMO Professional Level 6',4]],electives:[],maxElectives:0}
  };
  const builderPath=document.getElementById('builderPath'),coreModules=document.getElementById('coreModules'),electiveModules=document.getElementById('electiveModules'),selectedCredits=document.getElementById('selectedCredits'),targetCredits=document.getElementById('targetCredits'),progress=document.getElementById('builderProgress'),summary=document.getElementById('builderSummary');let selected=[];
  function renderBuilder(){const data=pathData[builderPath.value];selected=[];document.getElementById('builderTitle').textContent=data.title;document.getElementById('builderHint').textContent=data.hint;targetCredits.textContent=data.target;coreModules.innerHTML=data.core.map(([n,c])=>`<button class="builder-module locked" type="button" disabled><span><b>${n}</b><small>Mandatory core</small></span><em>${c} credit${c>1?'s':''}</em></button>`).join('');document.getElementById('electiveLabel').style.display=data.electives.length?'block':'none';electiveModules.innerHTML=data.electives.map(([n,c],i)=>`<button class="builder-module" type="button" data-index="${i}"><span><b>${n}</b><small>Select specialist option</small></span><em>${c} credit</em></button>`).join('');electiveModules.querySelectorAll('.builder-module').forEach(btn=>btn.addEventListener('click',()=>toggleElective(Number(btn.dataset.index))));updateBuilder();}
  function toggleElective(index){const data=pathData[builderPath.value];if(selected.includes(index))selected=selected.filter(i=>i!==index);else if(selected.length<data.maxElectives)selected=[...selected,index];updateBuilder();}
  function updateBuilder(){const data=pathData[builderPath.value];const core=data.core.reduce((s,x)=>s+x[1],0),elec=selected.reduce((s,i)=>s+data.electives[i][1],0),total=core+elec;selectedCredits.textContent=total;progress.style.width=`${Math.min(100,total/data.target*100)}%`;electiveModules.querySelectorAll('.builder-module').forEach((btn,i)=>{btn.classList.toggle('selected',selected.includes(i));btn.classList.toggle('disabled',!selected.includes(i)&&selected.length>=data.maxElectives)});const ready=total===data.target;summary.classList.toggle('ready',ready);summary.innerHTML=ready?`<b>Your ${data.title} reaches ${data.target} credits.</b><p>Use this selection as the starting point for your role, employer, funding and evidence conversation.</p>`:`<b>${data.maxElectives-selected.length} specialist selection${data.maxElectives-selected.length===1?'':'s'} remaining.</b><p>Choose options until the selected credits reach ${data.target}.</p>`;}
  builderPath.addEventListener('change',renderBuilder);renderBuilder();

  const appTabs=[...document.querySelectorAll('.application-tab')],appPanels=[...document.querySelectorAll('.application-panel')];appTabs.forEach((tab,i)=>tab.addEventListener('click',()=>{appTabs.forEach((t,j)=>{const on=i===j;t.classList.toggle('active',on);t.setAttribute('aria-selected',String(on));appPanels[j].classList.toggle('active',on)})}));

  const questionsData=['Have you been resident in the UK for the past 3 years?','Do you have the right to work without requiring new sponsorship for this route?','Are you free from other government-funded training at the same time?','Are you in paid employment in England for at least 16 hours per week and not self-employed?','Is your employer based in England and registered with the Apprenticeship Service?','Do you spend at least 50% of your working hours in England?','Can your employer support the required paid learning time and relevant energy-sector workplace evidence?'];
  const answers=Array(questionsData.length).fill(null),questionsEl=document.getElementById('questions');questionsEl.innerHTML=questionsData.map((q,i)=>`<div class="question"><label>${i+1}. ${q}</label><div class="answer-row"><button class="answer" data-q="${i}" data-v="yes" type="button">Yes</button><button class="answer" data-q="${i}" data-v="no" type="button">No</button><button class="answer" data-q="${i}" data-v="unsure" type="button">Not sure</button></div></div>`).join('');questionsEl.querySelectorAll('.answer').forEach(btn=>btn.addEventListener('click',()=>{const q=Number(btn.dataset.q);answers[q]=btn.dataset.v;questionsEl.querySelectorAll(`[data-q="${q}"]`).forEach(b=>b.classList.toggle('selected',b===btn));updateEligibility()}));
  function updateEligibility(){const answered=answers.filter(Boolean).length,yes=answers.filter(v=>v==='yes').length,no=answers.filter(v=>v==='no').length;document.getElementById('resultMeter').style.width=`${answered/answers.length*100}%`;const title=document.getElementById('resultTitle'),copy=document.getElementById('resultCopy');if(answered<answers.length){title.textContent=`${answered} of ${answers.length} answered`;copy.textContent='Complete all questions to receive initial access-route guidance.';return}if(yes>=6&&no===0){title.textContent='The DfE Funded Route may be suitable.';copy.textContent='Your answers match several initial indicators. A full KBC assessment is still required before funding can be confirmed.'}else if(yes>=4){title.textContent='An adviser review is recommended.';copy.textContent='Some indicators support the Funded Route, while others may require clarification. The IPC Bursary Route can also be considered.'}else{title.textContent='The IPC Bursary Route may be more suitable.';copy.textContent='Your answers suggest the DfE route may be difficult to access. IPC bursary support and flexible instalments may provide an alternative, subject to approval.'}}

  document.querySelectorAll('.faq-q').forEach(btn=>btn.addEventListener('click',()=>{const open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open))}));
})();
